import sys

class NumberTheory:
    class Mod998:
        def __init__(self):
            self.mod = 998

        def add(self, a, b):
            return (a + b) % self.mod

        def mult(self, a, b, *args):
            result = (a * b) % self.mod
            for arg in args:
                result = (result * (arg % self.mod)) % self.mod
            return result

        def div(self, a, b):
            return self.mult(a, self.smallInv(b))

        def smallInv(self, b):
            # Fermat's little theorem for prime mod
            return pow(b, self.mod - 2, self.mod)

        def fInv(self, n):
            # Placeholder for factorial inverse precomputation if needed
            pass

        def ncr(self, n, r):
            # Compute nCr modulo 998
            if r > n or r < 0:
                return 0
            numerator = 1
            denominator = 1
            for i in range(r):
                numerator = (numerator * (n - i)) % self.mod
                denominator = (denominator * (i + 1)) % self.mod
            return self.mult(numerator, self.smallInv(denominator))

        def paritySign(self, k):
            # Returns 1 if k is odd, -1 if even
            return 1 if k % 2 == 1 else -1

class CardShufflerSolver:
    def __init__(self):
        self.mod = NumberTheory.Mod998()

    def execute(self, in_stream, out_stream):
        totalCards = int(in_stream.readNext())
        totalShuffles = int(in_stream.readNext())

        self.mod.fInv(totalCards + totalShuffles)

        phaseSize = 1
        p = 1
        i = 0
        while p != 0:
            p = self.mod.mult(p, totalCards - i, self.mod.smallInv(totalShuffles + totalCards - i))
            phaseSize = self.mod.add(phaseSize, p)
            i += 1

        answer = 0
        for k in range(1, totalCards + 1):
            sign = self.mod.paritySign(k + 1)
            numPhases = self.mod.div(totalShuffles + k, k)
            term = self.mod.mult(sign, self.mod.ncr(totalCards, k), numPhases, phaseSize)
            answer = self.mod.add(answer, term)

        out_stream.println(answer)

class DataInput:
    def __init__(self, stream):
        self.lines = sys.stdin.read().splitlines()
        self.index = 0
        self.tokens = []
        self.token_index = 0

    def readNext(self):
        while self.token_index >= len(self.tokens):
            if self.index >= len(self.lines):
                raise RuntimeError("No more input")
            self.tokens = self.lines[self.index].split()
            self.index += 1
            self.token_index = 0
        token = self.tokens[self.token_index]
        self.token_index += 1
        return token

    def readNextInt(self):
        return int(self.readNext())

class PrintWriter:
    def __init__(self):
        self.output = []

    def println(self, value):
        self.output.append(str(value))
        print(value)

if __name__ == "__main__":
